constexpr unsigned BC1=0, BC3=1, BC5=2, BC7=3;
__device__ unsigned char chan(uchar4 c,unsigned k){return k==0?c.x:k==1?c.y:k==2?c.z:c.w;}
__device__ void setchan(uchar4& c,unsigned k,unsigned char v){if(k==0)c.x=v;else if(k==1)c.y=v;else if(k==2)c.z=v;else c.w=v;}
__device__ uchar4 px(const uchar4* s,unsigned x,unsigned y,unsigned w,unsigned h){return s[min(y,h-1)*w+min(x,w-1)];}
__device__ unsigned rgb565(float r,float g,float b){return (unsigned)(r*31+.5f)<<11|(unsigned)(g*63+.5f)<<5|(unsigned)(b*31+.5f);}
__device__ float3 dec565(unsigned v){return make_float3(((v>>11)&31)/31.f,((v>>5)&63)/63.f,(v&31)/31.f);}
__device__ unsigned near3(float3 c,float3 a,float3 b){float3 p[4]={a,b,make_float3((2*a.x+b.x)/3,(2*a.y+b.y)/3,(2*a.z+b.z)/3),make_float3((a.x+2*b.x)/3,(a.y+2*b.y)/3,(a.z+2*b.z)/3)};unsigned r=0;float d=1e30f;for(unsigned i=0;i<4;++i){float3 q=make_float3(c.x-p[i].x,c.y-p[i].y,c.z-p[i].z),e=make_float3(q.x*q.x,q.y*q.y,q.z*q.z);float z=e.x+e.y+e.z;if(z<d)d=z,r=i;}return r;}
__device__ unsigned near16(float3 c,float3 a,float3 b){unsigned r=0;float d=1e30f;for(unsigned i=0;i<16;++i){float f=i/15.f;float3 p=make_float3(a.x+(b.x-a.x)*f,a.y+(b.y-a.y)*f,a.z+(b.z-a.z)*f),q=make_float3(c.x-p.x,c.y-p.y,c.z-p.z);float z=q.x*q.x+q.y*q.y+q.z*q.z;if(z<d)d=z,r=i;}return r;}
__device__ float endpointErr(const uchar4* s,unsigned w,unsigned h,unsigned bx,unsigned by,float3 a,float3 b){float total=0;for(unsigned i=0;i<16;++i){uchar4 c=px(s,bx*4+i%4,by*4+i/4,w,h);float3 v=make_float3(c.x/255.f,c.y/255.f,c.z/255.f),q=make_float3(0,0,0);float best=1e30f;for(unsigned j=0;j<16;++j){float f=j/15.f;float3 p=make_float3(a.x+(b.x-a.x)*f,a.y+(b.y-a.y)*f,a.z+(b.z-a.z)*f);float3 d=make_float3(v.x-p.x,v.y-p.y,v.z-p.z);float e=d.x*d.x+d.y*d.y+d.z*d.z;if(e<best)best=e;}total+=best;}return total;}
__device__ unsigned ai(float v,float lo,float hi){float p[8]={hi,lo,0,0,0,0,0,0};for(unsigned i=2;i<8;++i)p[i]=((8-i)*hi+(i-1)*lo)/7;unsigned r=0;float d=1e30f;for(unsigned i=0;i<8;++i){float z=fabsf(v-p[i]);if(z<d)d=z,r=i;}return r;}
__device__ unsigned aw(const uchar4* s,unsigned w,unsigned h,unsigned bx,unsigned by,unsigned ch,unsigned word){float lo=1,hi=0;for(unsigned i=0;i<16;++i){float v=chan(px(s,bx*4+i%4,by*4+i/4,w,h),ch)/255.f;lo=fminf(lo,v);hi=fmaxf(hi,v);}unsigned r=word?0:((unsigned)(hi*255+.5f)|((unsigned)(lo*255+.5f)<<8));for(unsigned i=0;i<16;++i){uchar4 c=px(s,bx*4+i%4,by*4+i/4,w,h);unsigned v=ai(chan(c,ch)/255.f,lo,hi),bit=16+i*3;for(unsigned k=0;k<3;++k)if((bit+k)/32==word)r|=((v>>k)&1)<<((bit+k)&31);}return r;}
__device__ void put(unsigned* b,int bit,int n,unsigned v){for(int i=0;i<n;++i)if((v>>i)&1)b[(bit+i)>>5]|=1u<<((bit+i)&31);}
__global__ void resizeK(const uchar4* s,uchar4* d,unsigned sw,unsigned sh,unsigned dw,unsigned dh){unsigned x=blockIdx.x*blockDim.x+threadIdx.x,y=blockIdx.y*blockDim.y+threadIdx.y;if(x>=dw||y>=dh)return;float sx=(x+.5f)*sw/dw-.5f,sy=(y+.5f)*sh/dh-.5f;unsigned x0=(unsigned)max(0.f,floorf(sx)),y0=(unsigned)max(0.f,floorf(sy));float fx=sx-floorf(sx),fy=sy-floorf(sy);uchar4 a=px(s,x0,y0,sw,sh),b=px(s,x0+1,y0,sw,sh),c=px(s,x0,y0+1,sw,sh),e=px(s,x0+1,y0+1,sw,sh),o;for(int k=0;k<4;++k)setchan(o,k,(unsigned char)fminf(255.f,(1-fy)*((1-fx)*chan(a,k)+fx*chan(b,k))+fy*((1-fx)*chan(c,k)+fx*chan(e,k))));d[y*dw+x]=o;}
__global__ void compressK(const uchar4* s,unsigned* d,unsigned w,unsigned h,unsigned f){unsigned bx=blockIdx.x*blockDim.x+threadIdx.x,by=blockIdx.y*blockDim.y+threadIdx.y;if(bx*4>=w||by*4>=h)return;unsigned base=(by*((w+3)/4)+bx)*(f==BC1?2:4);float3 lo=make_float3(1,1,1),hi=make_float3(0,0,0);for(unsigned i=0;i<16;++i){uchar4 c=px(s,bx*4+i%4,by*4+i/4,w,h);lo.x=fminf(lo.x,c.x/255.f);lo.y=fminf(lo.y,c.y/255.f);lo.z=fminf(lo.z,c.z/255.f);hi.x=fmaxf(hi.x,c.x/255.f);hi.y=fmaxf(hi.y,c.y/255.f);hi.z=fmaxf(hi.z,c.z/255.f);}unsigned e0=rgb565(hi.x,hi.y,hi.z),e1=rgb565(lo.x,lo.y,lo.z);if(e0<e1){unsigned t=e0;e0=e1;e1=t;}float3 a=dec565(e0),b=dec565(e1);if(f==BC7){float3 llo=make_float3(1,1,1),lhi=make_float3(0,0,0);float minL=1e30f,maxL=-1e30f;for(unsigned i=0;i<16;++i){uchar4 c=px(s,bx*4+i%4,by*4+i/4,w,h);float3 v=make_float3(c.x/255.f,c.y/255.f,c.z/255.f),n=make_float3(.2126f*v.x+.7152f*v.y+.0722f*v.z,0,0);if(n.x<minL)minL=n.x,llo=v;if(n.x>=maxL)maxL=n.x,lhi=v;}if(endpointErr(s,w,h,bx,by,llo,lhi)<endpointErr(s,w,h,bx,by,a,b))a=llo,b=lhi;}unsigned ind=0;for(unsigned i=0;i<16;++i){uchar4 c=px(s,bx*4+i%4,by*4+i/4,w,h);ind|=near3(make_float3(c.x/255.f,c.y/255.f,c.z/255.f),a,b)<<(2*i);}if(f==BC1){d[base]=e0|(e1<<16);d[base+1]=ind;return;}if(f==BC3){d[base]=aw(s,w,h,bx,by,3,0);d[base+1]=aw(s,w,h,bx,by,3,1);d[base+2]=e0|(e1<<16);d[base+3]=ind;return;}if(f==BC5){d[base]=aw(s,w,h,bx,by,0,0);d[base+1]=aw(s,w,h,bx,by,0,1);d[base+2]=aw(s,w,h,bx,by,1,0);d[base+3]=aw(s,w,h,bx,by,1,1);return;}unsigned q[4]={0,0,0,0};put(q,0,7,64);int bit=7;for(int k=0;k<4;++k){float v=k==0?hi.x:k==1?hi.y:k==2?hi.z:1;put(q,bit,7,(unsigned)(v*127+.5f));bit+=7;}for(int k=0;k<4;++k){float v=k==0?lo.x:k==1?lo.y:k==2?lo.z:1;put(q,bit,7,(unsigned)(v*127+.5f));bit+=7;}put(q,63,1,0);put(q,64,1,0);bit=65;for(unsigned i=0;i<16;++i){uchar4 c=px(s,bx*4+i%4,by*4+i/4,w,h);put(q,bit,i?4:3,near16(make_float3(c.x/255.f,c.y/255.f,c.z/255.f),a,b));bit+=i?4:3;}for(int i=0;i<4;++i)d[base+i]=q[i];}
static bool ok(cudaError_t e,const char* what,std::string* err){if(e==cudaSuccess)return true;if(err)*err=std::string(what)+": "+cudaGetErrorString(e);return false;}
}  // namespace

CudaProcessor::CudaProcessor(const std::string& s):selector_(s){}
CudaProcessor::~CudaProcessor(){if(stream_)cudaStreamDestroy((cudaStream_t)stream_);if(input_)cudaFree(input_);if(hdrInput_)cudaFree(hdrInput_);if(hdrResized_)cudaFree(hdrResized_);if(resized_)cudaFree(resized_);if(compressed_)cudaFree(compressed_);}
bool CudaProcessor::init(std::string* err){int n=0;if(!ok(cudaGetDeviceCount(&n),"cudaGetDeviceCount",err)||!n){if(err&&n==0)*err="no CUDA devices";return false;}for(int i=0;i<n;++i){cudaDeviceProp p{};if(cudaGetDeviceProperties(&p,i)!=cudaSuccess)continue;std::string a=p.name,b=selector_;for(char& c:a)c=char(std::tolower((unsigned char)c));for(char& c:b)c=char(std::tolower((unsigned char)c));if(selector_.empty()||a.find(b)!=std::string::npos){device_=i;break;}}if(device_<0){if(err)*err="no CUDA device matches --device";return false;}cudaDeviceProp p{};if(!ok(cudaGetDeviceProperties(&p,device_),"cudaGetDeviceProperties",err)||!ok(cudaSetDevice(device_),"cudaSetDevice",err)||!ok(cudaStreamCreate((cudaStream_t*)&stream_),"cudaStreamCreate",err))return false;info_.backend="cuda";info_.name=p.name;info_.driver=std::to_string(p.major)+"."+std::to_string(p.minor);info_.hardware=true;info_.supportsBC1=info_.supportsBC3=info_.supportsBC5=info_.supportsBC7=true;info_.supportsBC6H=true;return true;}
bool CudaProcessor::process(const TextureRequest& r,TextureResult* out,std::string* err){if(!r.width||!r.height)return ok(cudaErrorInvalidValue,"invalid request",err);unsigned dw=std::max(1u,r.dstWidth),dh=std::max(1u,r.dstHeight);size_t co=CompressedSize(r.format,dw,dh);cudaStream_t s=(cudaStream_t)stream_;cudaEvent_t a,u,b,c;cudaEventCreate(&a);cudaEventCreate(&u);cudaEventCreate(&b);cudaEventCreate(&c);cudaEventRecord(a,s);if(r.format==CompressionFormat::BC6H){if(!r.rgbf||r.rgbfBytes<size_t(r.width)*r.height*3*sizeof(float)){if(err)*err="BC6H requires HDR float input";return false;}size_t bytes=size_t(r.width)*r.height*3*sizeof(float);if(hdrInputCapacity_<bytes){if(hdrInput_)cudaFree(hdrInput_);if(!ok(cudaMalloc(&hdrInput_,bytes),"cudaMalloc HDR input",err))return false;hdrInputCapacity_=bytes;}if(compressedCapacity_<co){if(compressed_)cudaFree(compressed_);if(!ok(cudaMalloc(&compressed_,co),"cudaMalloc compressed",err))return false;compressedCapacity_=co;}size_t hdrOutBytes=size_t(dw)*dh*3*sizeof(float);if(hdrResizedCapacity_<hdrOutBytes){if(hdrResized_)cudaFree(hdrResized_);if(!ok(cudaMalloc(&hdrResized_,hdrOutBytes),"cudaMalloc HDR resized",err))return false;hdrResizedCapacity_=hdrOutBytes;}if(!ok(cudaMemcpyAsync(hdrInput_,r.rgbf,bytes,cudaMemcpyHostToDevice,s),"cudaMemcpy HDR",err))return false;cudaEventRecord(u,s);hdr_gpu::resizeCuda<<<dim3((dw+15)/16,(dh+15)/16),dim3(16,16),0,s>>>((const float*)hdrInput_,(float*)hdrResized_,r.width,r.height,dw,dh);if(!ok(cudaGetLastError(),"HDR resize",err))return false;cudaEventRecord(b,s);bc6h_gpu::encodeCuda<<<dim3((dw+31)/32,(dh+31)/32),dim3(8,8),0,s>>>((const float*)hdrResized_,(unsigned*)compressed_,dw,dh,dw,dh);if(!ok(cudaGetLastError(),"BC6H kernel",err))return false;cudaEventRecord(c,s);if(!ok(cudaEventSynchronize(c),"cudaEventSynchronize",err))return false;out->width=dw;out->height=dh;out->compressed.resize(co);out->resizedRGBF.resize(size_t(dw)*dh*3);if(!ok(cudaMemcpy(out->compressed.data(),compressed_,co,cudaMemcpyDeviceToHost),"cudaMemcpy BC6H",err)||!ok(cudaMemcpy(out->resizedRGBF.data(),hdrResized_,hdrOutBytes,cudaMemcpyDeviceToHost),"cudaMemcpy HDR resized",err))return false;float up=0,rz=0,cp=0;cudaEventElapsedTime(&up,a,u);cudaEventElapsedTime(&rz,u,b);cudaEventElapsedTime(&cp,b,c);out->timing.uploadMs=up;out->timing.resizeGpuMs=rz;out->timing.compressGpuMs=cp;out->timing.totalMs=up+rz+cp;cudaEventDestroy(a);cudaEventDestroy(u);cudaEventDestroy(b);cudaEventDestroy(c);return true;}if(!r.rgba)return ok(cudaErrorInvalidValue,"RGBA input required",err);size_t in=size_t(r.width)*r.height*4,sz=size_t(dw)*dh*4;bool chainInput=ldrChainActive_&&ldrChainWidth_==r.width&&ldrChainHeight_==r.height;if(!r.deviceMipChain&&!chainInput)ldrChainActive_=false;auto grow=[&](void** p,size_t* cap,size_t need,const char* n){if(*cap>=need)return true;if(*p)cudaFree(*p);if(!ok(cudaMalloc(p,need),n,err))return false;*cap=need;return true;};if(!grow(&input_,&inputCapacity_,in,"cudaMalloc input")||!grow(&resized_,&resizedCapacity_,sz,"cudaMalloc resized")||!grow(&compressed_,&compressedCapacity_,co,"cudaMalloc compressed"))return false;if(chainInput)std::swap(input_,resized_),std::swap(inputCapacity_,resizedCapacity_);if(!chainInput&&!ok(cudaMemcpyAsync(input_,r.rgba,in,cudaMemcpyHostToDevice,s),"cudaMemcpy HtoD",err))return false;cudaEventRecord(u,s);resizeK<<<dim3((dw+15)/16,(dh+15)/16),dim3(16,16),0,s>>>((const uchar4*)input_,(uchar4*)resized_,r.width,r.height,dw,dh);if(!ok(cudaGetLastError(),"resizeK",err))return false;cudaEventRecord(b,s);if(r.format==CompressionFormat::ASTC){astc_gpu::encodeCuda<<<dim3((dw+31)/32,(dh+31)/32),dim3(8,8),0,s>>>((const uchar4*)resized_,(unsigned*)compressed_,dw,dh);if(!ok(cudaGetLastError(),"ASTC kernel",err))return false;}else{unsigned f=r.format==CompressionFormat::BC1?BC1:r.format==CompressionFormat::BC3?BC3:r.format==CompressionFormat::BC5?BC5:BC7;compressK<<<dim3((dw+31)/32,(dh+31)/32),dim3(8,8),0,s>>>((const uchar4*)resized_,(unsigned*)compressed_,dw,dh,f);if(!ok(cudaGetLastError(),"compressK",err))return false;}cudaEventRecord(c,s);if(!ok(cudaEventSynchronize(c),"cudaEventSynchronize",err))return false;out->width=dw;out->height=dh;out->compressed.resize(co);if(!r.deviceMipChain||r.downloadResized)out->resizedRGBA.resize(sz);if(!ok(cudaMemcpy(out->compressed.data(),compressed_,co,cudaMemcpyDeviceToHost),"cudaMemcpy DtoH",err)||((!r.deviceMipChain&&!ok(cudaMemcpy(out->resizedRGBA.data(),resized_,sz,cudaMemcpyDeviceToHost),"cudaMemcpy resized",err))||(r.deviceMipChain&&r.downloadResized&&!ok(cudaMemcpy(out->resizedRGBA.data(),resized_,sz,cudaMemcpyDeviceToHost),"cudaMemcpy resized",err))))return false;ldrChainActive_=r.deviceMipChain;ldrChainWidth_=dw;ldrChainHeight_=dh;float up=0,rz=0,cp=0;cudaEventElapsedTime(&up,a,u);cudaEventElapsedTime(&rz,u,b);cudaEventElapsedTime(&cp,b,c);out->timing.uploadMs=up;out->timing.resizeGpuMs=rz;out->timing.compressGpuMs=cp;out->timing.totalMs=up+rz+cp;cudaEventDestroy(a);cudaEventDestroy(u);cudaEventDestroy(b);cudaEventDestroy(c);return true;}
}  // namespace tusdview_texture_bench
